// Module 16 evidence: one real appliance installed from a package generated by the dev stack (its image pinned to
// this Control Plane's license key); the verdict on the overview and health pages; the license suspended on the
// Control Plane and the appliance's banner, status pill and disabled "Sync now" captured; the license resumed and
// the renewed verdict captured. Writes license-sample.json (states only, never token values). Removes the appliance.
// Usage: node scripts/screenshots-m16.mjs
import { spawn, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-16/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const hostIp = sh(`ip -4 route get 1.1.1.1 | awk '{for(i=1;i<=NF;i++) if($i=="src") print $(i+1)}'`).out;

const API_KEY = `demo-${Math.random().toString(36).slice(2, 10)}`;
const caPath = join(realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m16ca-'))), 'ca.pem');
const fake = spawn(process.execPath, [fileURLToPath(new URL('./fake-psa.mjs', import.meta.url)), hostIp, API_KEY, caPath], { stdio: ['ignore', 'pipe', 'inherit'] });
const port = await new Promise((resolve, reject) => {
  fake.stdout.on('data', (d) => { for (const line of String(d).split(/\r?\n/)) { const m = /^PORT (\d+)$/.exec(line); if (m) resolve(Number(m[1])); } });
  fake.on('exit', (code) => reject(new Error(`fake PSA exited with ${code}`)));
});

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true, focus = null) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  if (focus) await p.locator(focus).first().scrollIntoViewIfNeeded(); // bring the row under test into the viewport capture
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};
const waitFor = async (fn, ms, label) => { const end = Date.now() + ms; while (Date.now() < end) { if (await fn()) return; await sleep(2000); } throw new Error(`timed out: ${label}`); };

const keyInfo = await api('GET', '/settings/licensing-key');
const client = (await api('GET', '/clients?status=active&pageSize=50')).items.find((c) => c.code !== 'CL-00001');
const services = await api('GET', `/clients/${client.id}/services`);
const instance = await api('POST', '/psa-instances', {
  clientId: client.id, providerKey: 'custom_rest', displayName: `${client.displayName} — Demo PSA ${Date.now().toString(36)}`, authMethod: 'api_key',
  config: { baseUrl: `https://${hostIp}:${port}/api`, healthPath: '/health', apiKeyHeader: 'X-API-Key', ticketsPath: '/tickets' }, enabledServiceIds: services.filter((s) => s.requiresPsa).map((s) => s.id),
});
const today = new Date().toISOString().slice(0, 10);
const demoLicense = await api('POST', '/licenses', { clientId: client.id, displayName: 'Help Desk Plus (demo)', startsAt: today, endsAt: null, maxDeployments: 2, notes: 'Created for the Module 16 walkthrough.' });
const dep = await api('POST', '/deployments', { clientId: client.id, psaInstanceId: instance.id, licenseId: demoLicense.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module16-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m16-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m16shots/${project}`;
const adminPort = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unix = (p) => sh(`wslpath -a '${p}'`).out;
const adminBase = `http://127.0.0.1:${adminPort}`;
const curl = (args) => sh(`curl -s -o /tmp/psacc-m16shots/body -w '%{http_code}' -b /tmp/psacc-m16shots/jar -c /tmp/psacc-m16shots/jar ${args}; echo; cat /tmp/psacc-m16shots/body`, 60_000).out;
const agentState = () => { const r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-agent edge-agent status`, 60_000); try { return JSON.parse(r.out); } catch { return {}; } };
const sample = { deployment: dep.code, client: client.code, license: demoLicense.code, controlPlaneKeyId: keyInfo.keyId, steps: [] };

try {
  let r = sh(`rm -rf /tmp/psacc-m16shots && mkdir -p /tmp/psacc-m16shots && cd /tmp/psacc-m16shots && unzip -q "${unix(join(winTmp, pkg.fileName))}" && cd ${project} && grep -c '"keyId": "${keyInfo.keyId}"' config/license.json && cp config/edge.env.template .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).lifecycleState === 'verified', 180_000, 'verified');
  const pw = `demo-${dep.code}-local-admin-pass`;
  curl(`-X POST --data-urlencode username=localadmin --data-urlencode password=${pw} --data-urlencode confirm=${pw} ${adminBase}/setup`);
  const token = /name="csrf" value="([^"]+)"/.exec(curl(`${adminBase}/credentials`))[1];
  curl(`-X POST --data-urlencode csrf=${token} --data-urlencode field_apiKey=${API_KEY} --data-urlencode "field_tlsCaCertificate@${unix(caPath)}" ${adminBase}/credentials`);
  if (!curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`).includes('Connection verified')) throw new Error('the appliance test did not verify');
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).applianceLicense?.state === 'valid', 90_000, 'verdict reported');
  const st0 = agentState();
  sample.steps.push({ step: 'installed', applianceLicense: (await api('GET', `/deployments/${dep.id}`)).applianceLicense, agentKeyId: st0.license?.keyId, keySource: st0.license?.keySource });

  // 1. Dashboard: the verdict on the overview and the health page.
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '01-overview-appliance-license-valid', false, '[data-testid="appliance-license"]');
  await page.goto(`${base}/deployments/${dep.id}/health`, { waitUntil: 'networkidle' });
  await shot(page, '02-health-license-row', false);
  // 2. The appliance's own view.
  const edge = await browser.newContext({ viewport: { width: 1200, height: 900 }, deviceScaleFactor: 2 });
  const ep = await edge.newPage();
  await ep.goto(`http://localhost:${adminPort}/login`);
  await ep.getByLabel('User name').fill('localadmin');
  await ep.getByLabel('Password').fill(pw);
  await ep.getByRole('button', { name: 'Sign in' }).click();
  await ep.goto(`http://localhost:${adminPort}/`, { waitUntil: 'networkidle' });
  await ep.getByTestId('license-state').waitFor();
  await shot(ep, '03-appliance-license-valid', false);

  // 3. Suspend the license on the Control Plane: within a heartbeat the appliance stops PSA work.
  await api('POST', `/licenses/${demoLicense.id}/suspend`, { reason: 'Invoice overdue' });
  await waitFor(async () => agentState().license?.state === 'revoked', 90_000, 'appliance saw the inactive license');
  await sleep(3000);
  await ep.goto(`http://localhost:${adminPort}/`, { waitUntil: 'networkidle' });
  await ep.getByTestId('license-banner').waitFor();
  await shot(ep, '04-appliance-license-revoked-banner', false);
  await ep.goto(`http://localhost:${adminPort}/sync`, { waitUntil: 'networkidle' });
  await shot(ep, '05-appliance-sync-blocked', false);
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).applianceLicense?.state === 'revoked', 90_000, 'revoked verdict reported');
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '06-overview-appliance-license-revoked', false, '[data-testid="appliance-license"]');
  await page.goto(`${base}/deployments/${dep.id}/health`, { waitUntil: 'networkidle' });
  await shot(page, '07-health-appliance-license-finding', false);
  sample.steps.push({ step: 'license-suspended', applianceLicense: (await api('GET', `/deployments/${dep.id}`)).applianceLicense, findings: (await api('GET', `/deployments/${dep.id}/health`)).findings.map((f) => f.code) });

  // 4. Resume: the next heartbeat renews the token.
  await api('POST', `/licenses/${demoLicense.id}/resume`, { reason: 'Paid' });
  await waitFor(async () => agentState().license?.state === 'valid', 90_000, 'token renewed');
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).applianceLicense?.state === 'valid', 90_000, 'valid verdict reported');
  await ep.goto(`http://localhost:${adminPort}/`, { waitUntil: 'networkidle' });
  await shot(ep, '08-appliance-license-renewed', false);
  await edge.close();
  await page.goto(`${base}/licenses/${demoLicense.id}`, { waitUntil: 'networkidle' });
  await shot(page, '09-license-detail-after-resume', false);
  sample.steps.push({ step: 'license-resumed', applianceLicense: (await api('GET', `/deployments/${dep.id}`)).applianceLicense });
  writeFileSync(`${outDir}license-sample.json`, JSON.stringify(sample, null, 2));
} finally {
  sh(`cd ${work} 2>/dev/null && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m16shots`);
  rmSync(winTmp, { recursive: true, force: true });
  fake.kill('SIGTERM');
  rmSync(caPath, { force: true });
  await browser.close();
}
